const cfg = $input.first().json;
const start = Number(cfg.page_start ?? 1);
const end = Number(cfg.page_end ?? 100);
const pages = [];
for (let p = start; p <= end; p++) {
  pages.push({
    json: {
      page: p,
      tipo: cfg.bling_tipo ?? 'T',
      criterio: cfg.bling_criterio ?? '5',
      bling_base_url: cfg.bling_base_url,
    },
  });
}
return pages;

const inputs = $('Paginas').all();
const outputs = $input.all();
let totalItens = 0;
let paginasComDados = 0;
let paginasVazias = 0;
let erros = 0;
let ultimaPaginaComDados = 0;
const errosDetalhe = [];

for (let i = 0; i < outputs.length; i++) {
  const page = inputs[i]?.json?.page ?? i + 1;
  const item = outputs[i].json;
  if (item.error) {
    erros += 1;
    errosDetalhe.push({ pagina: page, erro: item.error.type ?? item.error.message ?? 'erro' });
    continue;
  }
  const batch = item.data ?? [];
  const n = Array.isArray(batch) ? batch.length : 0;
  if (n === 0) {
    paginasVazias += 1;
    continue;
  }
  paginasComDados += 1;
  ultimaPaginaComDados = page;
  totalItens += n;
}

const cfg = $('Config').first().json;
const catalogoCompleto = paginasVazias > 0 && ultimaPaginaComDados > 0;

return [{
  json: {
    total_produtos_bling: totalItens,
    paginas_com_dados: paginasComDados,
    paginas_vazias: paginasVazias,
    erros_api: erros,
    ultima_pagina_com_dados: ultimaPaginaComDados,
    tipo: cfg.bling_tipo,
    criterio: cfg.bling_criterio,
    faixa_paginas: `${cfg.page_start}-${cfg.page_end}`,
    catalogo_provavelmente_completo: catalogoCompleto,
    observacao: catalogoCompleto
      ? 'Encontrou página vazia após dados — catálogo inteiro nesta faixa.'
      : ultimaPaginaComDados === Number(cfg.page_end)
        ? 'Última página ainda tinha dados — aumente page_end e rode de novo.'
        : 'Verifique erros ou credencial.',
    erros_detalhe: errosDetalhe.slice(0, 10),
  },
}];
